// Reports how much of lib/ the unit and widget tests cover. It never fails the
// build: coverage is a guide to what's untested, not a target.
//
//   flutter test --coverage && dart run tool/coverage_report.dart
//
// Prints the uncovered lines of each file so they are easy to find.
import 'dart:io';

/// Files the unit and widget tests can't reach. The e2e tests cover main.dart;
/// firebase_options.dart is generated by `flutterfire configure`.
const excluded = {'lib/main.dart', 'lib/firebase_options.dart'};

void main(List<String> args) {
  final lcov = File(args.isNotEmpty ? args.first : 'coverage/lcov.info');
  if (!lcov.existsSync()) {
    stderr.writeln('No ${lcov.path}; run `flutter test --coverage` first.');
    exit(1);
  }

  final uncovered = <String, List<int>>{};
  final reported = <String>{};
  var found = 0;
  var hit = 0;
  String? file;

  for (final line in lcov.readAsLinesSync()) {
    if (line.startsWith('SF:')) {
      file = _relative(line.substring(3));
      reported.add(file);
    } else if (line.startsWith('DA:') && file != null && !excluded.contains(file)) {
      final parts = line.substring(3).split(',');
      found++;
      if (int.parse(parts[1]) > 0) {
        hit++;
      } else {
        uncovered.putIfAbsent(file, () => []).add(int.parse(parts[0]));
      }
    }
  }

  final untested = Directory('lib')
      .listSync(recursive: true)
      .whereType<File>()
      .map((f) => f.path.replaceAll(r'\', '/'))
      .where((path) => path.endsWith('.dart') && !excluded.contains(path))
      .where((path) => !reported.contains(path))
      .toList()
    ..sort();

  final percent = found == 0 ? 0.0 : hit * 100 / found;
  stdout.writeln('Line coverage: ${percent.toStringAsFixed(2)}% ($hit of $found lines)');
  for (final entry in uncovered.entries) {
    stdout.writeln('  ${entry.key}: lines ${entry.value.join(', ')}');
  }
  for (final path in untested) {
    stdout.writeln('  $path: no test loads this file');
  }
}

String _relative(String path) {
  final normalized = path.replaceAll(r'\', '/');
  final index = normalized.indexOf('lib/');
  return index < 0 ? normalized : normalized.substring(index);
}
